// Initialize UI
document.addEventListener('DOMContentLoaded', () => {
    initFilters();
    renderNotes(notesData);
    animateCounters();
    initFAQ();

    // Initialize Animations
    if (window.AOS) {
        AOS.init({
            duration: 800,
            once: true
        });
    }
});

// Animate Stats Counters (Disabled as stats are now handled by stats.js real-time listener)
